CREATE VIEW v22892 AS SELECT *, ST_ASTEXT(ST_GEOMETRYFROMWKB(ST_ASWKB(GEOMETRYCOLLECTION(POINT(0, 0), MULTIPOINT(POINT(0, 0), POINT(1, 1)), LINESTRING(POINT(0, 0), POINT(10, 10)), MULTILINESTRING(LINESTRING(POINT(1, 2), POINT(1, 3))), POLYGON(LINESTRING(POINT(10, 20), POINT(1, 1), POINT(2, 2), POINT(10, 20))), MULTIPOLYGON(POLYGON(LINESTRING(POINT(0, 0), POINT(1, 0), POINT(1, 1), POINT(0, 0)))))))) AS x1, CAST(x5.v22788 / 1 AS SIGNED) AS x2 FROM v22777 AS x5 LEFT JOIN v22872 AS x4 ON x5.v22788 = x5.v22786 WHERE x5.v22785 = 2 AND x5.v22778 >= 3